-- Every postcode sector in Great Britain, from the ONS.
--
-- A sector was only ever made when a place was stamped inside it, and its
-- centre was the mean of the postcodes of the places Epic happened to know
-- there. So a district with two known places was two points, both where the
-- places were: WC1H was two sectors forty-five metres apart at Euston, and
-- under the centre rule 145 places within three hundred metres of them were
-- nearer an NW1 or WC1E sector. Seventy-three of the hundred and thirty-six
-- inner-London districts were drawn that way. Owner, 25 Sep 2026: "A district
-- drawn as one point is a structural fault, not a London one."
--
-- Source: ONS Postcode Directory, August 2026 (Office for National Statistics,
-- Open Government Licence v3.0; contains OS data © Crown copyright and
-- database right 2026, Royal Mail data © Royal Mail copyright and database
-- right 2026). Each row is the mean of the live postcodes in the sector;
-- `points` is how many, and `source` says where it came from. Terminated
-- postcodes are left out. 11,088 sectors.
--
-- A sector whose centre moves more than the reach matrix tolerates loses its
-- build markers, the same way `noteCell` drops them when a stamp nudges a
-- centre: `reach.refresh` then works its neighbours out again. Everything
-- else — the matrix rows, the ring tables — is left to the refresh that
-- already runs.

create temp table ons_sectors (label text, outcode text, lat double precision, lng double precision, points int) on commit drop;

-- Cells that are about to move further than the matrix tolerates (RECENTRE_KM
-- in reach.js is a quarter of a kilometre): their travel rows were worked out
-- from where they used to be.
delete from cell_builds b
 using geo_cells g, ons_sectors o
 where b.from_cell = g.code
   and g.code = 'sector:' || o.label
   and sqrt(((g.lat - o.lat) * 111320) ^ 2 + ((g.lng - o.lng) * 70000) ^ 2) > 250;

select 'sector:' || label, 'sector', label, 'GB', outcode, lat, lng, points, 'onspd-2026-08'
  from ons_sectors
on conflict (code) do update
   set lat = excluded.lat, lng = excluded.lng, points = excluded.points,
       outcode = excluded.outcode, source = excluded.source, updated_at = now();

